  return { p:A_FYLAB[A_YA.length+fi], revenue:rev, costOfRevenue:cor, tac:A(tac,'tac'), otherCor:A(cor-tac,'otherCor'), rnd:A(rnd,'rnd'),
    marketing:A(mkt,'marketing'), gAdmin:A(ga,'gAdmin'), other:0 };
