    var ya=fb?+fb.getAttribute('data-brf'):GOOGL_OPEX_YEARS[0], yb2=tb?+tb.getAttribute('data-brt'):GOOGL_OPEX_YEARS[GOOGL_OPEX_YEARS.length-1], prev=GOOGL_OPEX[ya], cur=GOOGL_OPEX[yb2];
