function aOie(y){ var oi=aIsVal('oi',y), pt=aIsVal('pretax',y); return (oi==null||pt==null)?null:pt-oi; }
function aEtr(y){ var pt=aIsVal('pretax',y), tx=aIsVal('tax',y); return (pt&&tx!=null)?tx/pt:null; }
function aNormSubY(y){ var o=aOie(y), t=aEtr(y); return (o==null||t==null)?0:o*(1-t); }
