export function googlBlGeneralBuild(root){ if(root) _root=root; aBuildMargins(); aBuildExpenses(); }

// ═══ BL-SEG Bottom Line ▸ Segments (playbook §13 BL-SEG) — copied from meta-bl.js's segment section ═══
// Stacked, no picker: Profit by segment → Revenue vs profit → The segment bridge → Segment deep dives → footer.
// Adapted to what Alphabet discloses (SAB, Oct 26 2026): three segments plus "Alphabet-level activities" as its own line
// (the unallocated costs — general AI-model research, corporate costs, fines), so the four add up to income from
// operations. Segment revenue and operating income for all four; employee compensation and other costs for Services and
// Cloud only; no segment D&A (so no segment EBITDA). Bloomberg carries consensus operating income for every segment; the
// Summit model projects segment revenue but not segment profit, so Summit profit shows for Consolidated only.
function sPane(){ return R().querySelector('.dd-pane[data-dd="bottomline"] .ovt-subpane[data-ovst="segments"]'); }
var SEG_DEF=[{k:'svc',lab:'Google Services',c:SUMMIT_CAT[0],rk:'svc',ok:'svcop',bbg:'seg295814'},
             {k:'cloud',lab:'Google Cloud',c:SUMMIT_CAT[1],rk:'cloud',ok:'cloudop',bbg:'seg344781'},
             {k:'bets',lab:'Other Bets',c:SUMMIT_CAT[2],rk:'bets',ok:'betsop',bbg:'seg295791',loss:true},
             {k:'alpha',lab:'Alphabet-level (unallocated)',c:MUTE,rk:null,ok:'alphaop',bbg:'seg295833',loss:true}];
var SEG_CONS={k:'cons',lab:'Consolidated',c:INK,rk:'rev',ok:'opinc'};
var SEG_SPLIT=SEG_DEF.filter(function(s){ return s.k==='svc'||s.k==='cloud'; });   // the two with a cost split
function sSeg(k){ return k==='cons'?SEG_CONS:SEG_DEF.filter(function(s){ return s.k===k; })[0]||SEG_DEF[0]; }
function sNull(){ return null; }
// Annual axis: the reported years with segment operating income in the Results dataset, then the BBG forward years.
var S_YA=(function(){ var m=googlResults.views.y.metrics.svcop, o=[]; m.periods.forEach(function(p,i){ if(m.act[i]!=null) o.push(+p); }); return o; })();
var S_LA=S_YA.length-1;
var S_YRS=S_YA.concat(A_YF.filter(function(y){ return y>S_YA[S_LA]; }));
var S_LAB=S_YRS.map(function(y,i){ return fyLab(y)+(i>S_LA?'E':''); });
function rY(mk, src){ var m=mk&&googlResults.views.y.metrics[mk];
  return S_YRS.map(function(y){ if(!m||!m[src]) return null; var i=m.periods.indexOf(String(y)); return i>=0?m[src][i]:null; }); }
function sumQ(mk, y){ var m=mk&&googlResults.views.q.metrics[mk]; if(!m||!m.summit) return null; var t=0;
  for(var q=1;q<=4;q++){ var i=m.periods.indexOf(q+'Q'+String(y).slice(2)); if(i<0||m.summit[i]==null) return null; t+=m.summit[i]; } return t; }
function sumY(mk){ var a=rY(mk,'summit'); return S_YRS.map(function(y,i){ return a[i]!=null?a[i]:sumQ(mk,y); }); }
function bbgF(s){ return S_YRS.map(function(y,i){ if(i<=S_LA||!s||!s.f) return null; var j=A_YF.indexOf(y); return j>=0?s.f[j]:null; }); }
function consRevY(k){ return k==='cons'?bbgF(googlBBG.is.rev):(sSeg(k).rk?bbgF((googlBBG.seg[sSeg(k).bbg]||{}).rev):S_YRS.map(sNull)); }
function consOiY(k){ return bbgF(k==='cons'?googlBBG.is.oi:(googlBBG.seg[sSeg(k).bbg]||{}).oi); }
function sB(v){ return v==null?'—':(v<0?'−':'')+'$'+(Math.abs(v)/1000).toFixed(1)+'B'; }
function sPct(v){ return v==null?'—':(v<0?'−':'')+Math.abs(v).toFixed(1)+'%'; }
function sLastIdx(a){ var j=-1; (a||[]).forEach(function(v,i){ if(v!=null) j=i; }); return j; }
// Operating income of a segment in a year: reported, or Bloomberg consensus for a forward year.
function sOiY(y, s){ var i=S_YRS.indexOf(y); if(i<0) return null; return i<=S_LA?rY(s.ok,'act')[i]:consOiY(s.k)[i]; }

// ── 1 · Profit by segment — Actual vs Summit vs Consensus (operating income) ──
function sProfitBody(){
  return aStdScaffold({ id:'gg-segfc', title:'Profit by segment — Actual vs Summit vs Consensus', height:340,
    modes:[{cls:'seg',label:'Segment',opts:SEG_DEF.concat([SEG_CONS]).map(function(s,i){ return {v:s.k,label:s.lab,on:i===0}; })},
           {cls:'gran',label:'Period',opts:[{v:'y',label:'Annual',on:true},{v:'q',label:'Quarterly'}]}],
    presets:[['all','All'],['rep','Reported'],['fwd','Forward'],['l5','Last 5']] });
}
function sBuildProfit(){
  aStdRender('gg-segfc', function(st){
    var s=sSeg(st.modes.seg||'svc'), gran=st.modes.gran||'y', loss=!!s.loss, lab=loss?'Op. loss':'Op. income';
    var labels, la, act, sum, con, rA, rS, rC;
    if(gran==='q'){ var Q=googlResults.views.q.metrics, o=Q[s.ok], r=s.rk?Q[s.rk]:null;
      labels=o.periods.slice(); la=aLastActIdx(o.act); act=o.act; sum=o.summit; con=o.cons; rA=r&&r.act; rS=r&&r.summit; rC=r&&r.cons; }
    else { labels=S_LAB.slice(); la=S_LA;
      act=rY(s.ok,'act').map(function(v,i){ return i<=la?v:null; }); sum=sumY(s.ok);
      con=consOiY(s.k); rA=rY(s.rk,'act'); rS=sumY(s.rk); rC=consRevY(s.k); }
    function amt(a){ return labels.map(function(_,i){ return a&&a[i]!=null?Math.round(a[i]/100)/10:null; }); }
    function marg(a,r){ return labels.map(function(_,i){ return (a&&a[i]!=null&&r&&r[i])?Math.round(a[i]/r[i]*1000)/10:null; }); }
    var series=[
      {k:'act$',grp:'act',src:'Actual',label:lab+' — Actual',color:ASTD_ACT,type:'bar',data:amt(act)},
      {k:'sum$',grp:'sum',src:SUM_SRC,label:lab+' — Summit',color:ASTD_SUMMIT,type:'bar',data:amt(sum)},
      {k:'con$',grp:'con',src:'Consensus',label:lab+' — Consensus',color:ASTD_CONS,type:'bar',data:amt(con)}];
    if(!loss) series.push(
      {k:'actM',grp:'act',src:'Actual',label:'Margin — Actual',color:ASTD_ACT,type:'line',yAxisID:'y2',data:marg(act,rA)},
      {k:'sumM',grp:'sum',src:SUM_SRC,label:'Margin — Summit',color:ASTD_SUMMIT,type:'line',yAxisID:'y2',data:marg(sum,rS)},
      {k:'conM',grp:'con',src:'Consensus',label:'Margin — Consensus',color:ASTD_CONS,type:'line',yAxisID:'y2',dash:true,data:marg(con,rC)});
    series=series.filter(function(x){ return x.data.some(function(v){ return v!=null; }); });
    var end=Math.max.apply(null, series.map(function(x){ return sLastIdx(x.data); }));   // end the axis at the last value
    if(end>=0 && end<labels.length-1){ labels=labels.slice(0,end+1); series.forEach(function(x){ x.data=x.data.slice(0,end+1); }); }
    var notes=[];
    if(s.k!=='cons') notes.push('Operating income only: Alphabet discloses no D&amp;A by segment, so there is no segment EBITDA. Summit is not drawn — the model projects segment revenue but not segment profit. Consensus = Bloomberg’s segment operating income.');
    else notes.push('Consolidated = the three segments plus the unallocated Alphabet-level line. Summit is the model frozen at its dated snapshot; Consensus is the Bloomberg export.');
    if(s.k==='cloud'){ var CO=googlResults.views.q.metrics.cloudop, CR=googlResults.views.q.metrics.cloud, cl=aLastActIdx(CO.act);
      notes.push('The Cloud margin ladder (relocated from the Margins panel): the quarterly operating margin went from '+sPct(CO.act[0]/CR.act[0]*100)+' in '+esc(CO.periods[0])+' to '+sPct(CO.act[cl]/CR.act[cl]*100)+' in '+esc(CO.periods[cl])+'; Wiz adds a low-single-digit-point headwind for the rest of 2026 (CFO, 1Q26 call).'); }
    if(s.k==='alpha') notes.push('Alphabet-level activities are the costs the 10-K does not allocate to segments: “'+esc(GOOGL_SEG_ALLOC.unallocated)+'” They have no revenue of their own (hedging gains and losses on revenue are also kept here), so there is no margin.');
    if(s.k==='bets') notes.push('No margin line for Other Bets: its loss is several times its revenue, so a margin does not read.');
    var out={ labels:labels, lastAct:la, type:'bar', stacked:false, series:series, note:notes.join(' '),
      yFmt:function(x){ return (x<0?'−$':'$')+(x==null?'':Math.abs(x).toFixed(1))+'B'; }, y2Fmt:function(x){ return x+'%'; } };
    if(loss) out.legCap='Bars = operating loss, $B'; else out.paired=true;
    return out;
  });
}

// ── 2 · Revenue vs profit — common size by segment ──
function sMixBody(){
  return aStdScaffold({ id:'gg-segmix', title:'Revenue vs profit — common size by segment', height:340,
    metricSel:[{v:'rev',label:'Revenue',on:true,group:'Revenue'},{v:'oi',label:'Operating income',group:'Profit'}],
    modes:[{cls:'basis',label:'Basis',opts:[{v:'cons',label:'Actual + Consensus',on:true},{v:'summit',label:'Actual + Summit'}]},
           {cls:'show',label:'Show',opts:[{v:'amt',label:'$B',on:true},{v:'share',label:'Share'},{v:'growth',label:'Growth'}]},
           {cls:'layout',label:'Layout',opts:[{v:'stack',label:'Stacked',on:true},{v:'side',label:'Side by side'}]},
           {cls:'gran',label:'Period',opts:[{v:'y',label:'Annual',on:true},{v:'q',label:'Quarterly'}]},
           {cls:'cmp',label:'Compare',opts:[{v:'yoy',label:'YoY',on:true},{v:'qoq',label:'QoQ'}]},
           {cls:'gin',label:'Growth in',opts:[{v:'pct',label:'%',on:true},{v:'add',label:'$ added'}]}],
    presets:[['all','All'],['rep','Reported'],['fwd','Forward']] });
}
function sBuildMix(){
  aStdRender('gg-segmix', function(st){
    var metric=st.sel||'rev', basis=st.modes.basis||'cons', show=st.modes.show||'amt', layout=st.modes.layout||'stack', gran=st.modes.gran||'y';
    var cmp=st.modes.cmp||'yoy', gin=st.modes.gin||'pct', notes=[];
    if(metric==='oi'){ basis='cons';
      if(show==='share'){ show='amt'; notes.push('Share is not drawn for operating income: Other Bets and the Alphabet-level line lose money, so the shares would run above 100% and below zero. Shown in $B instead.'); }
      notes.push('Forward = Bloomberg’s consensus operating income by segment (the Summit model does not project segment profit). Other Bets and the Alphabet-level line sit below zero; the line is consolidated operating income.'); }
    else notes.push('Revenue = the three segments; hedging gains and losses on revenue (kept at the Alphabet level, under $0.3B a year) are left out.');
    if(basis==='summit') gran='y';
    var Q=googlResults.views.q.metrics, labels, la;
    if(gran==='q'){ labels=Q.svc.periods.slice(); la=aLastActIdx(Q.svc.act); } else { labels=S_LAB.slice(); la=S_LA; }
    function raw(s){ var mk=metric==='rev'?s.rk:s.ok; if(!mk) return null;
      if(gran==='q'){ var m=Q[mk]; return labels.map(function(_,i){ return i<=la?m.act[i]:(m.cons?m.cons[i]:null); }); }
      var ac=rY(mk,'act'), fw=basis==='summit'?rY(mk,'summit'):(metric==='rev'?consRevY(s.k):consOiY(s.k));
      return labels.map(function(_,i){ return i<=la?ac[i]:fw[i]; }); }
    var step=gran==='q'?(cmp==='qoq'?1:4):1, addMode=(show==='growth'&&gin==='add');
    var rows=SEG_DEF.map(function(s){ return { s:s, v:raw(s) }; }).filter(function(r){ return r.v; });
    var totals=labels.map(function(_,i){ var t=0, any=false; rows.forEach(function(r){ if(r.v[i]!=null){ t+=r.v[i]; any=true; } }); return any?t:null; });
    function val(v, pv, tot){ if(v==null) return null;
      if(show==='share') return tot?Math.round(v/tot*1000)/10:null;
      if(show==='growth'){ if(pv==null) return null; if(addMode) return Math.round((v-pv)/100)/10; return !pv?null:Math.round((v-pv)/Math.abs(pv)*1000)/10; }
      return Math.round(v/100)/10; }
    var series=rows.map(function(r){ return { k:r.s.k, label:r.s.lab, color:r.s.c, type:'bar',
      data:labels.map(function(_,i){ return val(r.v[i], r.v[i-step], totals[i]); }) }; });
    if(metric==='oi'&&show==='amt') series.push({ k:'tot', label:'Consolidated operating income', color:INK, type:'line', stack:'tot',
      data:totals.map(function(v){ return v==null?null:Math.round(v/100)/10; }) });
    var end=Math.max.apply(null, series.map(function(x){ return sLastIdx(x.data); }));
    if(end>=0 && end<labels.length-1){ labels=labels.slice(0,end+1); series.forEach(function(x){ x.data=x.data.slice(0,end+1); }); }
    if(metric==='oi'&&show==='growth'&&!addMode) notes.push('For Other Bets and the Alphabet-level line a negative change means the loss widened.');
    if(basis==='summit') notes.push('Actual through '+esc(labels[la])+', then the Summit model (frozen) — annual only.');
    var stacked=show==='share'||(show==='amt'&&layout==='stack')||(addMode&&layout==='stack');
    var yFmt=(show==='amt'||addMode)?function(x){ return (x<0?'−$':'$')+(x==null?'':Math.abs(x).toFixed(1))+'B'; }:function(x){ return x+'%'; };
    var hide=[]; if(!(show==='growth'&&gran==='q')) hide.push('cmp'); if(show!=='growth') hide.push('gin'); if(show==='share') hide.push('layout');
    if(basis==='summit') hide.push('gran'); if(metric==='oi') hide.push('basis');
    return { labels:labels, lastAct:la, yFmt:yFmt, type:'bar', stacked:stacked, yMax:show==='share'?100:undefined, series:series, hideModes:hide, note:notes.join(' ') };
  });
}

// ── 3 · The segment bridge — By segment (Δ operating income per segment, reported and consensus years) | By cost ──
var SBR_QS=GOOGL_SEG_Q.filter(function(r,i){ return i>=4; });   // quarters with a same-quarter-last-year row
var SEG_YRS=Object.keys(GOOGL_SEG_Y).map(Number).sort();
function sBridgeBody(){
  function yB(cls, ys, sel){ return ys.map(function(y){ return '<button type="button" data-'+cls+'="'+y+'"'+(y===sel?' class="active"':'')+'>'+fyLab(y)+(y>S_YA[S_LA]?'E':'')+'</button>'; }).join(''); }
  var nS=S_YA.length, nC=SEG_YRS.length, qL=SBR_QS[SBR_QS.length-1].p;
  return '<div class="ov-sec"><div class="ov-sec-h">The segment bridge — what moved operating income</div>'+
    '<div class="mch-ctl"><span class="acx-tog sbr-mode"><button type="button" data-sbrm="seg" class="active">By segment</button><button type="button" data-sbrm="cost">By cost — revenue, pay, other costs</button></span><span></span></div>'+
    '<div class="sbr-ctl-seg mch-ctl me-bl-ctl"><span></span><span class="me-bl-pills">'+
      '<span class="me-bl-lbl">From</span><span class="acx-tog sbr-from">'+yB('sbrf',S_YRS,S_YA[Math.max(0,nS-4)])+'</span>'+
      '<span class="me-bl-lbl">to</span><span class="acx-tog sbr-to">'+yB('sbrt',S_YRS,S_YA[nS-1])+'</span></span></div>'+
    '<div class="sbr-ctl-cost mch-ctl me-bl-ctl" hidden>'+
      '<span class="acx-tog sbr-seg">'+SEG_SPLIT.map(function(s,i){ return '<button type="button" data-sbrs="'+s.k+'"'+(i===0?' class="active"':'')+'>'+esc(s.lab)+'</button>'; }).join('')+'</span>'+
      '<span class="me-bl-pills"><span class="acx-tog sbr-gran"><button type="button" data-sbrg="y" class="active">Annual</button><button type="button" data-sbrg="q">Quarterly</button></span>'+
        '<span class="sbr-cy"><span class="me-bl-lbl">From</span><span class="acx-tog sbr-cfrom">'+yB('sbrcf',SEG_YRS,SEG_YRS[nC-2])+'</span>'+
        '<span class="me-bl-lbl">to</span><span class="acx-tog sbr-cto">'+yB('sbrct',SEG_YRS,SEG_YRS[nC-1])+'</span></span>'+
        '<span class="acx-tog sbr-cq" hidden>'+SBR_QS.map(function(r){ return '<button type="button" data-sbrq="'+r.p+'"'+(r.p===qL?' class="active"':'')+'>'+r.p+'</button>'; }).join('')+'</span>'+
      '</span></div>'+
    '<div class="me-bl-h340"><canvas id="ggSegBr"></canvas></div>'+
    '<div id="ggSegBr-tbl" class="me-bl-tblhost"></div>'+
    '<div class="acx-cap me-bl-note" id="ggSegBrCap"></div></div>';
}
function sAct(p, mk){ var m=googlResults.views.y.metrics[mk], i=m.periods.indexOf(String(p)); return i>=0?m.act[i]:null; }
function sBridgeSync(pane){
  var mb=pane.querySelector('.sbr-mode .active'), mode=mb?mb.getAttribute('data-sbrm'):'seg';
  aShow(pane.querySelector('.sbr-ctl-seg'), mode==='seg'); aShow(pane.querySelector('.sbr-ctl-cost'), mode==='cost');
  var g=pane.querySelector('.sbr-gran .active'), q=!!(g&&g.getAttribute('data-sbrg')==='q');
  aShow(pane.querySelector('.sbr-cy'), !q); aShow(pane.querySelector('.sbr-cq'), q);
}
function sBuildBridge(){
  var pane=sPane(); if(!pane) return;
  var mb=pane.querySelector('.sbr-mode .active'), mode=mb?mb.getAttribute('data-sbrm'):'seg', cap=pane.querySelector('#ggSegBrCap'), steps;
  function A(sel,attr){ var b=pane.querySelector(sel+' .active'); return b?b.getAttribute(attr):null; }
  function fy(y){ return fyLab(y)+(y>S_YA[S_LA]?'E':''); }
  if(mode==='seg'){
    var y0=+A('.sbr-from','data-sbrf'), y1=+A('.sbr-to','data-sbrt');
    if(!(y1>y0)){ aDestroy('ggSegBr'); var tw=$id('ggSegBr-tbl'); if(tw) tw.innerHTML=''; if(cap) cap.innerHTML='Pick a “to” year after the “from” year.'; return; }
    var v0=SEG_DEF.map(function(s){ return sOiY(y0,s); }), v1=SEG_DEF.map(function(s){ return sOiY(y1,s); });
    if(v0.concat(v1).some(function(v){ return v==null; })){ aDestroy('ggSegBr'); if(cap) cap.innerHTML='No segment operating income for one of the two years.'; return; }
    var t0=v0.reduce(function(a,v){ return a+v; },0)/1000, run=t0;
    steps=[{label:fy(y0)+' op. income', kind:'base', color:INK, range:[0,run], runAfter:run, val:run}];
    var parts=SEG_DEF.map(function(s,i){ var d=(v1[i]-v0[i])/1000, lo=run; run=lo+d;
      steps.push({label:s.lab, kind:d>=0?'up':'down', color:s.c, dc:d>=0?POS:NEG, range:[Math.min(lo,run),Math.max(lo,run)], runAfter:run, val:d}); return d; });
    steps.push({label:fy(y1)+' op. income', kind:'total', color:POS, range:[0,run], runAfter:null, val:run});
    aBuildBrWaterfall('ggSegBr', steps, BR_FMT_D);
    if(cap) cap.innerHTML='Operating income went from <b>'+sB(t0*1000)+'</b> in '+fy(y0)+' to <b>'+sB(run*1000)+'</b> in '+fy(y1)+': '+
      SEG_DEF.map(function(s,i){ return esc(s.lab)+' '+(parts[i]>=0?'added':'took')+' <b>'+sB(Math.abs(parts[i])*1000)+'</b>'; }).join(', ')+
      '. The three segments and the unallocated Alphabet-level line add up to income from operations. Source: Results dataset (10-K and 10-Q segment notes)'+(y1>S_YA[S_LA]?'; '+fy(y1)+' = Bloomberg consensus operating income by segment (as of '+esc(googlBBG.asOf)+')':'')+'.';
    return;
  }
  var k=A('.sbr-seg','data-sbrs')||'svc', s=sSeg(k), gq=A('.sbr-gran','data-sbrg')==='q', a, b, la, lb;
  if(gq){ var qp=A('.sbr-cq','data-sbrq')||SBR_QS[SBR_QS.length-1].p, iq=GOOGL_SEG_Q.map(function(r){ return r.p; }).indexOf(qp);
    b=GOOGL_SEG_Q[iq][k]; a=GOOGL_SEG_Q[iq-4][k]; lb=GOOGL_SEG_Q[iq].p; la=GOOGL_SEG_Q[iq-4].p; }
  else { var c0=+A('.sbr-cfrom','data-sbrcf'), c1=+A('.sbr-cto','data-sbrct');
    if(!(c1>c0)){ aDestroy('ggSegBr'); var tw2=$id('ggSegBr-tbl'); if(tw2) tw2.innerHTML=''; if(cap) cap.innerHTML='Pick a “to” year after the “from” year.'; return; }
    a=GOOGL_SEG_Y[c0][k]; b=GOOGL_SEG_Y[c1][k]; la=fyLab(c0); lb=fyLab(c1); }
  var r0=a.oi/1000, run2=r0;
  steps=[{label:la+' op. income', kind:'base', color:INK, range:[0,run2], runAfter:run2, val:r0}];
  function st2(lab, d){ var lo=run2; run2=lo+d; steps.push({label:lab, kind:d>=0?'up':'down', color:d>=0?POS:NEG, range:[Math.min(lo,run2),Math.max(lo,run2)], runAfter:run2, val:d}); }
  st2('Revenue', (b.rev-a.rev)/1000); st2('Employee comp.', -(b.comp-a.comp)/1000); st2('Other costs', -(b.other-a.other)/1000);
  steps.push({label:lb+' op. income', kind:'total', color:b.oi>=0?POS:NEG, range:[0,run2], runAfter:null, val:run2});
  aBuildBrWaterfall('ggSegBr', steps, BR_FMT_D);
  if(cap){ var mA=a.rev?a.oi/a.rev*100:null, mB=b.rev?b.oi/b.rev*100:null;
    cap.innerHTML='<b>'+esc(s.lab)+'</b>, '+la+' → '+lb+': revenue '+(b.rev>=a.rev?'added':'took')+' <b>'+sB(Math.abs(b.rev-a.rev))+'</b>, employee compensation '+(b.comp>=a.comp?'took':'gave back')+' <b>'+sB(Math.abs(b.comp-a.comp))+'</b> and other costs '+(b.other>=a.other?'took':'gave back')+' <b>'+sB(Math.abs(b.other-a.other))+'</b> — operating margin '+sPct(mA)+' → '+sPct(mB)+'.'+
      (gq?' Each quarter is compared with the same quarter a year earlier.':'')+' Alphabet splits segment costs into these two lines only, and only for Google Services and Google Cloud. Source: '+GOOGL_SEG_SRC+'.'; }
}

// ── 4 · Segment deep dives (collapsible) — one tab per segment, same formal layout as the Expense lines ──
var S_DY=S_YA.slice(-5);   // the margin bars: last five reported years
function sSpark(vals, labs, fmt){ var mx=Math.max.apply(null,vals.map(function(v){ return Math.abs(v||0); }))||1;
  return '<div class="ew-spark">'+vals.map(function(v,i){ return '<div class="ew-sb'+(i===vals.length-1?' on':'')+'"><div class="ew-sb-v">'+fmt(v)+'</div><div class="ew-sb-bar" style="height:'+Math.max(2,Math.round(Math.abs(v||0)/mx*72))+'px"></div><div class="ew-sb-l">'+labs[i]+'</div></div>'; }).join('')+'</div>'; }
function sCostTable(k){
  var qL=GOOGL_SEG_Q[GOOGL_SEG_Q.length-1], qP=GOOGL_SEG_Q[GOOGL_SEG_Q.length-5];
  var rows=SEG_YRS.map(function(y){ return [fyLab(y), GOOGL_SEG_Y[y][k]]; }).concat([[qP.p, qP[k]],[qL.p, qL[k]]]);
  return '<div class="twrap ew-twrap"><table class="rt ew-tbl"><thead><tr><th>Period</th><th>Revenue</th><th>Employee comp.</th><th>Other costs</th><th>Op. income</th><th>Op. margin</th></tr></thead><tbody>'+
    rows.map(function(r){ var d=r[1], m=d.rev?d.oi/d.rev:null;
      return '<tr><td class="ew-tk">'+r[0]+'</td><td>'+sB(d.rev)+'</td><td>'+sB(d.comp)+'</td><td>'+sB(d.other)+'</td><td>'+sB(d.oi)+'</td><td>'+(m==null?'—':sPct(m*100))+'</td></tr>'; }).join('')+
    '</tbody></table></div>';
}
function sQ(mk, p){ var m=googlResults.views.q.metrics[mk], i=m.periods.indexOf(p); return i>=0?m.act[i]:null; }
function sDive(d){
  var k=d.k, s=sSeg(k), yL=S_YA[S_LA], loss=!!s.loss, split=!!GOOGL_SEG_Y[SEG_YRS[SEG_YRS.length-1]][k];
  var rev=sAct(yL,s.rk), oi=sAct(yL,s.ok), totRev=sAct(yL,'rev');
  var Qo=googlResults.views.q.metrics[s.ok], li=aLastActIdx(Qo.act), qL=Qo.periods[li], qP=Qo.periods[li-4];
  var qo=sQ(s.ok,qL), qr=sQ(s.rk,qL), po=sQ(s.ok,qP), pr=sQ(s.rk,qP);
  var kp=[[sB(rev), fyLab(yL)+' revenue · '+sPct(rev/totRev*100)+' of Alphabet'],
    loss?[sB(oi), fyLab(yL)+' operating loss · '+(Math.abs(oi)/rev).toFixed(1)+'× revenue']:[sB(oi), fyLab(yL)+' operating income · '+sPct(oi/rev*100)+' margin'],
    loss?[sB(qo), qL+' operating loss ('+sB(po)+' in '+qP+')']:[sB(qo), qL+' operating income · '+sPct(qo/qr*100)+' margin ('+sPct(po/pr*100)+' in '+qP+')']];
  if(split){ var cur=GOOGL_SEG_Y[SEG_YRS[SEG_YRS.length-1]][k]; kp.push([sPct(cur.comp/(cur.comp+cur.other)*100), 'of '+fyLab(SEG_YRS[SEG_YRS.length-1])+' segment costs is employee compensation']); }
  var h='<div class="ew-h">Key figures</div><div class="ov-kpis">'+kp.map(function(x){ return '<div class="ov-kpi"><div class="ov-kpi-v">'+x[0]+'</div><div class="ov-kpi-d muted">'+x[1]+'</div></div>'; }).join('')+'</div>';
  h+='<div class="ew-h">Definition — Form 10-K</div><div class="ew-q ew-def">“'+d.def+'”<span class="ew-att">— Alphabet Form 10-K for FY'+yL+', Note 15</span></div>';
  if(d.otherDef) h+='<div class="ew-q ew-def">“'+d.otherDef+'”<span class="ew-att">— what “other costs and expenses” contains · Form 10-Q for '+esc(GOOGL_SEG_Q[GOOGL_SEG_Q.length-1].p)+', segment note</span></div>';
  h+='<div class="ew-h">The business</div><div class="ew-note">'+d.business+'</div>';
  var oiS=S_DY.map(function(y){ return sAct(y,s.ok); }), rvS=S_DY.map(function(y){ return sAct(y,s.rk); });
  h+='<div class="ew-h">'+(loss?'Operating loss':'Operating margin')+', '+fyLab(S_DY[0])+'–'+fyLab(S_DY[S_DY.length-1])+'</div>'+
    (loss?sSpark(oiS.map(function(v){ return v/1000; }), S_DY.map(fyLab), function(v){ return '−$'+Math.abs(v).toFixed(1)+'B'; })
         :sSpark(oiS.map(function(v,i){ return rvS[i]?v/rvS[i]*100:null; }), S_DY.map(fyLab), function(v){ return v==null?'—':v.toFixed(0)+'%'; }));
  if(split) h+='<div class="ew-h">Cost split — what Alphabet breaks out by segment</div>'+sCostTable(k);
  h+='<div class="ew-h">What drives it</div><div class="twrap ew-twrap"><table class="rt ew-tbl"><tbody>'+d.moves.map(function(m){ return '<tr><td class="ew-tk">'+m[0]+'</td><td>'+m[1]+'</td></tr>'; }).join('')+'</tbody></table></div>';
  h+='<div class="ew-h">What the segment note discloses — and what it does not</div><div class="twrap ew-twrap"><table class="rt ew-tbl"><tbody>'+
    ewTableRows('Disclosed by segment', [['','Revenue, operating income','Revenue and operating income (loss), annual and quarterly'+(split?'; employee compensation and other costs and expenses.':' — no cost split for Other Bets.')]])+
    ewTableRows('Not disclosed by segment', [['','D&amp;A, capex, assets','No depreciation, capital expenditure or assets by segment, so no segment EBITDA or return on capital. “'+esc(GOOGL_SEG_ALLOC.codm)+'”'],
      ['','Income-statement lines','No cost of revenues, R&amp;D, sales and marketing or G&amp;A by segment — only the two-way split, for Google Services and Google Cloud.']])+
    ewTableRows('How costs reach a segment — Form 10-K Note 15', [['','Direct','“'+esc(GOOGL_SEG_ALLOC.direct)+'”'],['','Allocated','“'+esc(GOOGL_SEG_ALLOC.allocated)+'”'],['','Not allocated','“'+esc(GOOGL_SEG_ALLOC.unallocated)+'”']])+
    '</tbody></table></div>';
  h+=ewCallsTable(d.calls);
  h+='<div class="ov-foot">Sources: '+GOOGL_SEG_SRC+'; Results dataset for '+fyLab(S_DY[0])+'–'+fyLab(S_DY[S_DY.length-1])+' segment revenue and operating income; Alphabet’s official earnings-call transcripts (investor relations) for management commentary.</div>';
  return h;
}
function sDivesBody(){
  var yL=S_YA[S_LA];
  var tabs=GOOGL_SEG_DIVES.map(function(d,i){ var s=sSeg(d.k), oi=sAct(yL,s.ok), rv=sAct(yL,s.rk);
    var tag=s.loss?sB(oi)+' op. loss':sB(oi)+' · '+sPct(oi/rv*100)+' margin';
    return '<button type="button" class="exp-tab'+(i===0?' active':'')+'" data-segtab="'+d.k+'"><span class="exp-dot" style="background:'+s.c+'"></span>'+esc(d.name)+' <span class="exp-tag">'+tag+' · '+fyLab(yL)+'</span></button>'; }).join('');
  return '<div class="exp-explorer exp-flat"><div class="exp-tabs">'+tabs+'</div><div class="exp-panels">'+
    GOOGL_SEG_DIVES.map(function(d,i){ return '<div class="exp-panel exp-panel-card" data-segpanel="'+d.k+'"'+(i>0?' hidden':'')+'>'+sDive(d)+'</div>'; }).join('')+'</div></div>';
}
function googlBlFootSegments(){
  var q=googlResults.views.q.metrics.svcop, qs=q.periods[0], snaps=aSummitSnaps();
  return '<div class="ov-foot">Sources — '+GOOGL_SEG_SRC+': segment employee compensation and other costs, '+fyLab(SEG_YRS[0])+'–'+fyLab(SEG_YRS[SEG_YRS.length-1])+' and '+esc(GOOGL_SEG_Q[0].p)+'–'+esc(GOOGL_SEG_Q[GOOGL_SEG_Q.length-1].p)+' (a Q4 is the year less the nine months); '+
    'Results dataset for segment revenue and operating income from '+fyLab(S_YA[0])+' and '+esc(qs)+', and for the Summit series — Summit DCF model, frozen (not live)'+(snaps.length?', snapshot '+snaps.map(esc).join(' and '):'')+'; '+
    'Bloomberg consensus export (BBG_CONSENSUS, as of '+esc(googlBBG.asOf)+') for segment revenue and operating income forward; Alphabet’s official earnings-call transcripts. Forward figures are estimates.</div>';
}
function sBuildSegments(){
  var pane=sPane(); if(!pane) return;
  aWireCollaps(pane);
  sBuildProfit(); sBuildMix(); sBridgeSync(pane); sBuildBridge();
  if(pane._segWired) return; pane._segWired=true;
  var tog=function(sel,after){ pane.querySelectorAll(sel+' button').forEach(function(b){ b.onclick=function(){ pane.querySelectorAll(sel+' button').forEach(function(x){ x.classList.toggle('active',x===b); }); after(); }; }); };
  ['.sbr-mode','.sbr-gran'].forEach(function(s){ tog(s, function(){ sBridgeSync(pane); sBuildBridge(); }); });
  ['.sbr-from','.sbr-to','.sbr-seg','.sbr-cfrom','.sbr-cto','.sbr-cq'].forEach(function(s){ tog(s, sBuildBridge); });
  var stabs=pane.querySelectorAll('.exp-tab[data-segtab]');
  stabs.forEach(function(b){ b.onclick=function(){ var key=b.getAttribute('data-segtab');
    stabs.forEach(function(x){ x.classList.toggle('active',x===b); });
    pane.querySelectorAll('.exp-panel[data-segpanel]').forEach(function(p){ p.hidden=(p.getAttribute('data-segpanel')!==key); }); }; });
}
// Mount: '<div class="ovt-subpane" data-ovst="segments">'+googlBlSegmentsHtml()+'</div>' in the Bottom Line pane;
// build lazily once visible: googlBlSegmentsBuild(root).
export function googlBlSegmentsHtml(){
  return '<div class="seg-gsec" data-sgsec="oimargin">'+sProfitBody()+'</div>'+
    '<div class="seg-gsec me-bl-gap" data-sgsec="mix">'+sMixBody()+'</div>'+
    '<div class="seg-gsec me-bl-gap" data-sgsec="bridge">'+sBridgeBody()+'</div>'+
    aCollap('Segment deep dives — Google Services, Google Cloud and Other Bets (key figures, cost split, drivers, what is disclosed, calls)', sDivesBody(), false)+googlBlFootSegments();
}
export function googlBlSegmentsBuild(root){ if(root) _root=root; sBuildSegments(); }
